function exploreBudgetAndProofs(params: { question_id: string }) {
  const files = listFiles();
  const budgetRelated = files.filter(f => f.includes('budget') || f.includes('Budget'));
  const proofRelated = files.filter(f => f.includes('proof') || f.includes('Proof'));
  const explorationRelated = files.filter(f => f.includes('explor') || f.includes('Explor'));
  const harnessRelated = files.filter(f => f.includes('harness') || f.includes('Harness'));

  return {
    budgetFiles: budgetRelated,
    proofFiles: proofRelated,
    explorationFiles: explorationRelated,
    harnessFiles: harnessRelated,
    allFiles: files
  };
}

