  const files = listFiles();
  const relevantFiles = files.filter(file => 
    file.includes('harness') || 
    file.includes('budget') || 
    file.includes('proof') || 
    file.includes('exploration') ||
    file.includes('verif') ||
    file.includes('complet')
  );

  const fileContents = relevantFiles.map(file => {
    const lines = readLines(file, 1, 100).lines;
    return { file, lines };
  });

  return { relevantFiles, fileContents };
}

